package main

import (
	"encoding/json"
	"log"
	"net/http"
	"sync"

	"github.com/gorilla/websocket"
)

type User struct {
	ID        string `json:"id"`
	Username  string `json:"username"`
	Email     string `json:"email"`
	Role      string `json:"role"`
	AvatarURL string `json:"avatar_url"`
	S3Bucket  string `json:"s3_bucket"`
	S3Prefix  string `json:"s3_prefix"`
	IsAdmin   bool   `json:"is_admin"`
}

type UpdateMessage struct {
	Action  string          `json:"action"`
	Payload json.RawMessage `json:"payload"`
}

var (
	users   = make(map[string]*User)
	usersMu sync.RWMutex
	upgrader = websocket.Upgrader{CheckOrigin: func(r *http.Request) bool { return true }}
)

func init() {
	users["user-001"] = &User{
		ID:        "user-001",
		Username:  "alice",
		Email:     "alice@example.com",
		Role:      "viewer",
		AvatarURL: "",
		S3Bucket:  "prod-user-assets-7f3a",
		S3Prefix:  "users/user-001/",
		IsAdmin:   false,
	}
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	// Authenticate from first message
	_, authMsg, err := conn.ReadMessage()
	if err != nil {
		return
	}
	var authPayload struct {
		Token  string `json:"token"`
		UserID string `json:"user_id"`
	}
	if err := json.Unmarshal(authMsg, &authPayload); err != nil {
		conn.WriteMessage(websocket.TextMessage, []byte(`{"error":"invalid auth"}`))
		return
	}

	userID := authPayload.UserID

	for {
		_, msg, err := conn.ReadMessage()
		if err != nil {
			break
		}

		var update UpdateMessage
		if err := json.Unmarshal(msg, &update); err != nil {
			continue
		}

		switch update.Action {
		case "update_profile":
			handleProfileUpdate(conn, userID, update.Payload)
		case "get_profile":
			handleGetProfile(conn, userID)
		}
	}
}

func handleProfileUpdate(conn *websocket.Conn, userID string, payload json.RawMessage) {
	usersMu.Lock()
	defer usersMu.Unlock()

	user, exists := users[userID]
	if !exists {
		conn.WriteMessage(websocket.TextMessage, []byte(`{"error":"user not found"}`))
		return
	}

	// Mass assignment vulnerability: unmarshal directly into user struct
	// This allows clients to set Role, IsAdmin, S3Bucket, S3Prefix
	if err := json.Unmarshal(payload, user); err != nil {
		conn.WriteMessage(websocket.TextMessage, []byte(`{"error":"invalid payload"}`))
		return
	}

	// Persist the user's S3 path for asset uploads
	// The service uses the user's S3Bucket and S3Prefix to scope uploads
	log.Printf("Updated user %s: bucket=%s prefix=%s role=%s admin=%v",
		user.ID, user.S3Bucket, user.S3Prefix, user.Role, user.IsAdmin)

	resp, _ := json.Marshal(map[string]interface{}{
		"status": "updated",
		"user":   user,
	})
	conn.WriteMessage(websocket.TextMessage, resp)
}

func handleGetProfile(conn *websocket.Conn, userID string) {
	usersMu.RLock()
	defer usersMu.RUnlock()

	user, exists := users[userID]
	if !exists {
		conn.WriteMessage(websocket.TextMessage, []byte(`{"error":"user not found"}`))
		return
	}

	resp, _ := json.Marshal(user)
	conn.WriteMessage(websocket.TextMessage, resp)
}

func main() {
	http.HandleFunc("/ws", handleWebSocket)
	log.Println("WebSocket server starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
